rows.script:
rule "King of the Hill"
global king: key
global bar: num
global crowned_at: time

payout 50% to king

on buy {
  let need = fade(bar, over: 6h, since: crowned_at)
  if amount > need {
    set king = buyer
    set bar = amount
    set crowned_at = clock.now
  }
}

on sell, send {
  refuse if wallet == king and since(crowned_at) < 6h
    because "You're the king: no selling or sending for {6h - since(crowned_at)}, unless someone outbids you"
}

rule "Cool down"
global cooldown_end: time

on sell {
  set cooldown_end = clock.now + 30s
}
on sell, send {
  refuse if cooldown_end > clock.now and since(cooldown_end) > 60d
    because "Cool down: no sells or sends for {cooldown_end - clock.now}"
}

rule "First minute lock"
# $LOCK. Anyone who buys in the first minute is locked for 1 hour.
# Sells are allowed after the hour, even if you hold a large amount.

wallet locked: bool
wallet lock_until: time

on buy {
  if coin.age < 1m {
    set wallet.locked = true
    set wallet.lock_until = clock.now + 1h
  }
}

on sell {
  refuse if wallet.locked and wallet.lock_until > clock.now
    because "You bought in the first minute: locked for {wallet.lock_until - clock.now}"
}

rule "Cool down"
on buy {
  set wallet.last_buy = clock.now
}
on sell {
  refuse if since(wallet.last_buy) < 10m
    because "Cool down: wait {10m - since(wallet.last_buy)}"
}

rule "Big Sell Lock"
# Sells bigger than 1% of supply are blocked for the first 3 hours.

on sell {
  refuse if coin.age < 3h and amount > supply * 1%
    because "Big sells are locked for {3h - coin.age}"
}

rule "Launch minute limit"
# Only 20 buys per minute across everyone during launch hour.

global buys_this_min: int
global last_reset: time

on buy {
  if coin.age >= 1h {
    set buys_this_min = 0
    set last_reset = clock.now
  } else {
    let elapsed = since(last_reset)
    let mins = elapsed / 60s
    if mins >= 1m {
      set buys_this_min = 0
      set last_reset = clock.now - 60s
    }
  }
  if buys_this_min >= 20 {
    refuse because "Too many buys this minute. {20 - buys_this_min} left"
  }
  set buys_this_min += 1
}

rule "Round buys only"
on buy {
  refuse if amount % 1000 != 0
    because "Buys must be a round number of tokens (multiple of 1,000)"
}

rule "Dev sells only"
global dev: key

on sell, send {
  refuse if wallet != coin.creator and since(coin.launch) < 12h
    because "Only the dev can sell. The lock expires in {12h - since(coin.launch)}"
}
